-- Généré par tests/build_guide.lua depuis GUIDE.itIT.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.itIT = {
    { "h1", "Guida di Panorama" },
    { "p", "Come usare Panorama su WoW Forever e come configurare l'HDR su Windows." },
    { "p", "|cffffd100Prima fai una copia delle tue impostazioni.|r Panorama modifica impostazioni del gioco, e rimuovere l'addon non le ripristina. Prima di cambiare qualsiasi cosa, chiudi il gioco e copia la cartella |cffffd100WTF|r della tua installazione del gioco in un posto sicuro. Per tornare indietro, chiudi il gioco e rimetti quella copia al suo posto." },
    { "h2", "1. Aprire la finestra" },
    { "li", "Digita |cffffd100/pano|r oppure fai clic sinistro sul pulsante di Panorama sulla minimappa.", "-" },
    { "li", "Anche in Opzioni > AddOn > Panorama c'è un pulsante che la apre.", "-" },
    { "li", "Trascina la barra del titolo per spostare la finestra. Escape o il pulsante di chiusura la chiude.", "-" },
    { "p", "Il pulsante della minimappa:" },
    { "li", "Il clic sinistro apre o chiude la finestra.", "-" },
    { "li", "Il clic destro mostra i preset, annulla, ripeti e il riavvio della grafica.", "-" },
    { "li", "Trascinalo per spostarlo intorno alla minimappa. |cffffd100/pano minimap|r lo mostra o lo nasconde.", "-" },
    { "h2", "2. La finestra" },
    { "row", "|cffffd100Semplice|r, |cffffd100Avanzato|r (accanto al titolo)", "Semplice: ogni scheda mostra un breve elenco delle impostazioni principali, senza sezioni. Avanzato: tutte le impostazioni, per sezione, con le regole per luogo e la sezione Esperti. Alla prima installazione è Semplice; se usavi già Panorama, è Avanzato. La ricerca trova sempre tutte le impostazioni." },
    { "row", "Guida (in alto a destra)", "Apre questa guida nel gioco." },
    { "row", "Menu |cffffd100Opzioni|r (in alto a destra)", "|cffffd100Lingua|r (lingua del gioco o una di dieci lingue; cambiarla ricarica l'interfaccia), |cffffd100Applica a ogni accesso|r, |cffffd100Pulsante minimappa|r, |cffffd100Ripristina tutto…|r." },
    { "row", "|cffffd100Aspetto attuale:|r (barra sotto il titolo)", "L'aspetto sul mondo adesso, e chi lo imposta: tu, Giorno e notte o il luogo. Il suo pulsante (|cffffd100Modifica|r, |cffffd100Modifica questa regola|r) apre dove cambiarlo. Passa il mouse sulla barra per vedere quale viene prima." },
    { "row", "Schede", "|cffffd100Immagine|r (qualità grafica), |cffffd100HDR|r, |cffffd100Atmosfera|r (aspetto del mondo), |cffffd100Miei filtri|r. La scheda aperta viene ricordata." },
    { "row", "Casella di ricerca (a destra delle schede)", "Digita una parola per elencare le impostazioni corrispondenti di tutte le schede. Cancellala per tornare indietro." },
    { "row", "Preset (scheda Immagine)", "Bassa, Media, Alta, Extra. Il preset che corrisponde alle tue impostazioni è evidenziato." },
    { "row", "Piè di pagina", "|cffffd100Annulla|r cancella la tua ultima modifica: cursore, casella, preset, filtro, atmosfera o Ripristina tutto. |cffffd100Ripeti|r la rimette. Le ultime 20 modifiche restano fino a |cffffd100/reload|r. |cffffd100Riavvia|r riavvia il motore grafico." },
    { "p", "In modalità Avanzato, fai clic sul titolo di una sezione per comprimerla o espanderla. La sezione |cffffd100Esperti (solo console)|r parte compressa. Il titolo di una sezione indica quante delle sue impostazioni hai cambiato." },
    { "h3", "Una riga di impostazione" },
    { "li", "|cffffd100Cursore|r: il valore viene scritto quando rilasci il pulsante del mouse, non mentre trascini.", "-" },
    { "li", "|cffffd100Casella del valore|r accanto al cursore: digita un valore, poi premi Invio o fai clic altrove. Escape annulla, Tab passa alla casella successiva. La virgola funziona come separatore decimale. Il valore resta nell'intervallo del cursore.", "-" },
    { "li", "|cffffd100Pulsante Predefinito|r: riporta quell'impostazione al suo valore predefinito. Passaci sopra con il mouse per vedere il valore.", "-" },
    { "li", "|cffffd100Segno dorato|r a sinistra: hai cambiato questa impostazione.", "-" },
    { "li", "|cffffd100Menu del gioco|r: quando anche un menu del gioco imposta questo valore, la guida dell'etichetta lo nomina. Quel menu non rilegge il valore, quindi può mostrare un altro livello.", "-" },
    { "li", "|cffffd100Riga in grigio|r: dipende da un'altra impostazione che è disattivata (per esempio |cffffd100Qualità della nebbia volumetrica|r senza |cffffd100Nebbia volumetrica|r, l'intensità della tinta senza una tinta), oppure una modalità la imposta. Passa il mouse sull'etichetta per vedere perché. Una riga che dipende da un'altra è spostata a destra, subito sotto.", "-" },
    { "li", "Passa il mouse su un'etichetta per leggere la sua guida completa.", "-" },
    { "h2", "3. Preset" },
    { "row", "Bassa", "Massime prestazioni. Visuale corta, senza ombre." },
    { "row", "Media", "Bilanciato. Buone prestazioni, ombre discrete." },
    { "row", "Alta", "Livello Alto del gioco. Ombre complete, tutti gli effetti." },
    { "row", "Extra", "Alta, con la visuale più lontana." },
    { "p", "I preset cambiano solo le impostazioni di qualità grafica della scheda Immagine. Non toccano fotocamera, mouse, interfaccia, nitidezza, bassa latenza, HDR né filtri." },
    { "p", "Hai cambiato idea? |cffffd100Annulla|r (piè di pagina, o |cffffd100/pano undo|r) ripristina le impostazioni di prima del preset." },
    { "h2", "4. Atmosfera" },
    { "p", "La scheda Atmosfera imposta l'aspetto del mondo: effetti sopra l'immagine. Non cambiano nessuna impostazione del gioco." },
    { "li", "|cffffd100Modalità|r (in alto nella scheda): |cffffd100Fisso|r (lo stesso filtro ovunque), |cffffd100Giorno e notte|r (una tinta diurna e una tinta notturna) o |cffffd100In base al luogo|r (vedi sotto). Fisso per impostazione predefinita.", "-" },
    { "li", "|cffffd100Qui|r: il luogo e l'ora del giorno rilevati adesso. Quando una spedizione, il chiuso o il meteo vengono prima di una zona che hai impostato, lo indica.", "-" },
    { "li", "|cffffd100Filtro|r (modalità Fisso e Giorno e notte): |cffffd100Base|r usa le righe sotto. Uno dei tuoi filtri (scheda Miei filtri) sostituisce la tinta, la vignettatura e la grana, e porta il suo contrasto, la sua luminosità e il suo gamma. |cffffd100Modifica filtro|r lo apre nella scheda Miei filtri.", "-" },
    { "li", "|cffffd100Tinta|r: fai clic su un'anteprima per applicarla subito (Seppia, Calda, Fredda, Notte, Smeraldo, Crepuscolo). |cffffd100Intensità della tinta|r imposta quanto è forte.", "-" },
    { "li", "|cffffd100Vignettatura|r: scurisce i bordi dello schermo.", "-" },
    { "li", "|cffffd100Grana|r: grana animata.", "-" },
    { "li", "|cffffd100Tinta diurna|r e |cffffd100Tinta notturna|r (modalità Giorno e notte): Panorama applica la tinta diurna di giorno e la tinta notturna di notte, secondo il giorno e la notte del gioco. Sostituiscono la tinta. Il passaggio è graduale dalle 19 alle 21 e dalle 5 alle 7 (ora del server). Uno dei tuoi filtri scelto nella riga Filtro le sostituisce.", "-" },
    { "li", "|cffffd100Cielo|r: gli stessi colori come sfumatura, pieni in alto sullo schermo e più chiari in basso. |cffffd100Intensità del cielo|r imposta quanto è forte.", "-" },
    { "li", "|cffffd100Bande nere|r: bande in alto e in basso, da 0 a 20 % dello schermo ciascuna, in ogni modalità. Il gioco continua a elaborare ciò che nascondono, quindi non aumentano il frame rate.", "-" },
    { "p", "In modalità Semplice, la scheda mostra la modalità, il luogo, il filtro, la tinta e la sua intensità, e le tinte diurna e notturna. Vignettatura, grana, cielo e bande nere sono in modalità Avanzato." },
    { "h3", "In base al luogo" },
    { "p", "Nella modalità |cffffd100In base al luogo|r, tinta, cielo, vignettatura e grana cambiano da soli, in base a dove ti trovi." },
    { "li", "Le righe della modalità Fisso sono nascoste: la regola del luogo le sostituisce. Restano solo le bande nere. I loro valori restano salvati e tornano quando cambi modalità. In modalità Semplice si applicano le regole fornite; scegli Avanzato per modificarle.", "-" },
    { "li", "|cffffd100Luogo|r: imposta tinta, vignettatura e grana. Ordine: spedizione o incursione, al chiuso, meteo (pioggia, neve, tempesta di sabbia), poi il tipo di zona: terre temperate, deserti e terre aride, terre innevate, giungla e palude, terre corrotte, terre vulcaniche, foreste arcane. Una zona non ancora nota conta come temperata. Il meteo conta solo se Intensità del meteo è maggiore di 0.", "-" },
    { "li", "|cffffd100Ora del giorno|r: imposta il cielo (giorno, alba e tramonto, notte). La notte segue il giorno e la notte del gioco; alba e tramonto seguono l'ora del server. Nessun cielo al chiuso o in una spedizione.", "-" },
    { "li", "|cffffd100Regola|r (modalità Avanzato): scegli una regola, poi regolala sotto. Il pulsante Predefinito rende il valore fornito per quella regola. La prima volta che la finestra si apre, la regola del luogo in cui ti trovi è aperta. Il menu ha cinque gruppi: |cffffd100Zone|r (la zona in cui ti trovi e quelle che hai impostato), |cffffd100Spedizione e interni|r, |cffffd100Meteo|r, |cffffd100Tipo di zona|r e |cffffd100Cielo (ora)|r. I primi quattro regolano tinta, vignettatura, grana e una preimpostazione grafica: si applica un solo luogo alla volta, nell'ordine indicato sopra. L'ultimo regola il cielo. Non serve regolare nulla per iniziare: ogni regola ha già i suoi valori.", "-" },
    { "li", "|cffffd100Questa zona|r: prima voce dello stesso menu, con il nome della zona in cui ti trovi. Sceglila per dare a questa zona una tinta, una vignettatura e una grana proprie, partendo dal suo tipo di zona. Passa allora prima del tipo di zona, ma dopo spedizione, al chiuso e meteo. Le zone che imposti restano nel menu. |cffffd100Torna al tipo di zona|r (accanto al menu) rimuove i valori della zona: torna a seguire il suo tipo di zona.", "-" },
    { "li", "|cffffd100Tutte le zone|r: sottomenu dello stesso menu, con tutte le zone conosciute. Scegline una per impostarla senza essere lì. Le zone sono ordinate per continente.", "-" },
    { "li", "|cffffd100Preimpostazione|r e |cffffd100Distanza dello scenario|r (sezione |cffffd100Immagine|r di un luogo o di una zona): si applicano finché sei in quel luogo, sopra le tue impostazioni, qualunque sia la modalità atmosfera. La distanza dello scenario del luogo viene prima di quella della preimpostazione. Le tue impostazioni restano salvate e tornano quando te ne vai. |cffffd100Le mie impostazioni|r non cambia nulla. Esempio: Bassa nelle spedizioni, Extra in una zona che ti piace. In una spedizione o incursione, la prima scelta del menu regola solo quella spedizione. Nella scheda Immagine, |cffffd100Qui: …|r compare accanto ai preset mentre un luogo applica i suoi; in modalità Avanzato, apre quella regola. In combattimento, la modifica attende la fine del combattimento.", "-" },
    { "li", "|cffffd100Filtro|r (prima riga della sezione |cffffd100Aspetto|r di un luogo o di una zona): questo luogo usa uno dei tuoi filtri della scheda Miei filtri, con il suo contrasto, la sua luminosità e il suo gamma. |cffffd100Impostazioni sotto|r: la tinta, la vignettatura e la grana della regola. La sezione Aspetto si applica solo in modalità In base al luogo.", "-" },
    { "h2", "5. Miei filtri" },
    { "p", "La scheda Miei filtri ti permette di creare tutti i filtri tuoi che vuoi. Il filtro aperto è mostrato sul mondo solo in anteprima; quello applicato si sceglie nella scheda Atmosfera. |cffffd100Nuovo|r ne aggiunge uno e lo apre, |cffffd100Elimina|r toglie quello aperto: il filtro della scheda Atmosfera e le regole che lo usavano tornano a nessun filtro. Resta sempre un filtro." },
    { "li", "|cffffd100Filtro|r: sceglie il filtro che le righe sotto regolano. |cffffd100Nome|r: dagli un nome (Invio per confermare).", "-" },
    { "li", "|cffffd100Tinta|r: fai clic su un'anteprima per dare al filtro quel colore. |cffffd100Rosso|r, |cffffd100Verde|r, |cffffd100Blu|r (in %): il suo colore esatto. |cffffd100Intensità della tinta|r: la sua forza.", "-" },
    { "li", "|cffffd100Vignettatura|r e |cffffd100Grana|r: quelle del filtro.", "-" },
    { "li", "|cffffd100Contrasto|r, |cffffd100Luminosità|r, |cffffd100Gamma|r: impostazioni dell'immagine che il filtro dà al gioco finché è applicato; poi tornano i tuoi valori. Le mie impostazioni: non cambia nulla. A seconda della modalità di visualizzazione possono restare senza effetto.", "-" },
    { "li", "In modalità Semplice, la scheda mostra solo la tinta e l'intensità della tinta.", "-" },
    { "li", "Finché la scheda è aperta, il filtro mostrato si vede in diretta sul gioco. La barra |cffffd100Aspetto attuale:|r indica quando è solo un'anteprima.", "-" },
    { "li", "Per usare un filtro: sceglilo nella riga |cffffd100Filtro|r della scheda Atmosfera (modalità Fisso e Giorno e notte), oppure di un luogo o di una zona (modalità In base al luogo). Sostituisce allora la tinta, la vignettatura e la grana. |cffffd100Base|r o |cffffd100Impostazioni sotto|r: non cambia nulla.", "-" },
    { "h2", "6. I tuoi valori e il gioco" },
    { "li", "Alla prima installazione, Panorama legge le impostazioni attuali del gioco. Non cambia nulla finché non muovi un controllo.", "-" },
    { "li", "Una modifica fatta nel menu Grafica del gioco o con |cffffd100/console|r compare nella finestra.", "-" },
    { "li", "|cffffd100Applica a ogni accesso|r (menu Opzioni, attivo per impostazione predefinita): le impostazioni che hai cambiato in Panorama vengono scritte di nuovo a ogni accesso. Le altre seguono il menu Grafica del gioco.", "-" },
    { "li", "Una modifica fatta durante il combattimento viene applicata quando il combattimento finisce.", "-" },
    { "li", "Alcune impostazioni, come MSAA, richiedono un riavvio della grafica. Fai clic su |cffffd100Riavvia|r nel piè di pagina o digita |cffffd100/pano restart|r. Lo schermo sfarfalla per un secondo.", "-" },
    { "h2", "7. HDR su Windows" },
    { "p", "Le impostazioni HDR esistono nel gioco solo come comandi della console. Panorama le mostra nella scheda |cffffd100HDR|r. Serve un monitor che supporti l'HDR." },
    { "h3", "Passo 1: attivare l'HDR in Windows" },
    { "p", "Windows 11:" },
    { "li", "Apri |cffffd100Impostazioni > Sistema > Schermo|r.", "1." },
    { "li", "Seleziona il monitor HDR se ne hai più di uno.", "2." },
    { "li", "Attiva |cffffd100Usa HDR|r. Anche la scorciatoia |cffffd100Win + Alt + B|r lo attiva o lo disattiva.", "3." },
    { "p", "Windows 10: |cffffd100Impostazioni > Sistema > Schermo > Impostazioni colore HD di Windows|r (Windows HD Color settings), poi attiva |cffffd100Riproduci app e giochi HDR|r (Play HDR games and apps)." },
    { "p", "Controlla anche che l'HDR sia attivo nel menu del monitor stesso, se ha questa opzione." },
    { "p", "Disattiva l'|cffffd100HDR automatico|r (Auto HDR) di Windows 11: |cffffd100Impostazioni > Sistema > Schermo > HDR|r. Serve ai giochi senza HDR. WoW produce la propria immagine HDR." },
    { "h3", "Passo 2: trovare la luminosità massima del tuo monitor" },
    { "p", "Installa l'app gratuita |cffffd100Calibrazione HDR di Windows|r (Windows HDR Calibration) dal Microsoft Store ed eseguila. La luminanza massima che trova è la luminosità massima del tuo monitor, in nit." },
    { "p", "Senza l'app, usa la classificazione HDR del monitor: DisplayHDR 400 significa circa 400 nit, DisplayHDR 600 circa 600, DisplayHDR 1000 circa 1000." },
    { "h3", "Passo 3: impostare l'HDR in Panorama" },
    { "p", "Apri |cffffd100/pano|r, scheda |cffffd100HDR|r. In modalità Semplice, la scheda mostra solo le prime tre righe qui sotto: scegli |cffffd100Avanzato|r per vedere |cffffd100Intensità HDR|r e la luminosità di riferimento." },
    { "li", "Spunta |cffffd100Uscita HDR|r.", "1." },
    { "li", "Spunta |cffffd100Usa luminosità di picco|r o |cffffd100Usa luminosità di riferimento|r: l'uno o l'altro, mai entrambi. Senza nessuno, l'immagine diventa scura.", "2." },
    { "p", "|cffffd100Modo luminosità massima (consigliato)|r" },
    { "li", "Spunta |cffffd100Usa luminosità di picco|r.", "-" },
    { "li", "Imposta |cffffd100Luminosità di picco (nit)|r sul valore trovato nel passo 2.", "-" },
    { "li", "|cffffd100Intensità HDR|r funziona solo in questo modo. Il valore predefinito del gioco è 2. Cambialo a piccoli passi e confronta: Blizzard non documenta il suo effetto esatto.", "-" },
    { "p", "|cffffd100Modo luminosità di riferimento|r" },
    { "li", "Spunta |cffffd100Usa luminosità di riferimento|r.", "-" },
    { "li", "|cffffd100Luminosità di riferimento (nit)|r è la luminosità del bianco nella scena. 203 è il valore standard. Aumentalo se l'immagine sembra troppo scura in una stanza luminosa. Intensità HDR non ha effetto in questo modo.", "-" },
    { "p", "Se l'immagine non cambia, fai clic su |cffffd100Riavvia|r nel piè di pagina." },
    { "h3", "Risoluzione dei problemi HDR" },
    { "row", "Immagine molto scura", "Spunta uno dei due modi di luminosità." },
    { "row", "Immagine grigia o sbiadita", "Attiva l'HDR in Windows (passo 1) e nel menu del monitor." },
    { "row", "HDR automatico attivo in Windows", "Disattivalo (passo 1)." },
    { "row", "Luci troppo forti o piatte", "Imposta la luminosità massima sul valore reale del tuo monitor (passo 2)." },
    { "row", "Vuoi l'HDR disattivato", "Togli la spunta a |cffffd100Uscita HDR|r." },
    { "p", "Ogni riga HDR ha un pulsante Predefinito che ripristina il valore del gioco." },
    { "h2", "8. Comandi" },
    { "row", "|cffffd100/pano|r", "Apre o chiude la finestra" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Applica un preset" },
    { "row", "|cffffd100/pano undo|r", "Annulla l'ultima modifica" },
    { "row", "|cffffd100/pano redo|r", "Rimette la modifica appena annullata" },
    { "row", "|cffffd100/pano reset|r", "Riporta ogni impostazione e ogni filtro al valore predefinito" },
    { "row", "|cffffd100/pano status|r", "Mostra nella chat il luogo e il momento rilevati e i filtri applicati ora (durante una dissolvenza, i valori di arrivo)" },
    { "row", "|cffffd100/pano apply|r", "Scrive di nuovo le impostazioni cambiate in Panorama" },
    { "row", "|cffffd100/pano restart|r", "Riavvia il motore grafico" },
    { "row", "|cffffd100/pano minimap|r", "Mostra o nasconde il pulsante della minimappa" },
    { "row", "|cffffd100/pano blackbars 10|r", "Bande nere al 10% dell'altezza dello schermo (da 0 a 20). |cffffd100off|r le toglie" },
    { "row", "|cffffd100/pano grain 10|r", "Grana a 10 (da 0 a 100). |cffffd100off|r la toglie" },
    { "row", "|cffffd100/pano vignette 10|r", "Vignettatura a 10 (da 0 a 100). |cffffd100off|r la toglie" },
    { "h2", "9. Ripristino" },
    { "li", "Il pulsante |cffffd100Predefinito|r di ogni riga ripristina quell'impostazione.", "-" },
    { "li", "Il pulsante |cffffd100Predefiniti|r del menu Grafica del gioco ripristina solo le impostazioni che quel menu gestisce, e Panorama lo segue. Usa i pulsanti Predefinito in |cffffd100/pano|r per le altre e per i filtri.", "-" },
    { "li", "|cffffd100Ripristina tutto…|r (menu Opzioni, con conferma) o |cffffd100/pano reset|r: riporta ogni impostazione della finestra, modificata in Panorama o no, e ogni filtro al valore predefinito. |cffffd100Annulla|r la annulla fino a |cffffd100/reload|r. Anche la scheda Atmosfera e le zone impostate vengono ripristinate. Anche i tuoi filtri della scheda Miei filtri vengono cancellati.", "-" },
}
